using namespace std;

void scan(int &x) {
    char c;
    x = 0;
    bool neg = false;
    while (!isdigit(c = getchar())) {
        if (c == '-') neg = true;
    }
    do {
        x = x * 10 + (c - '0');
    } while (isdigit(c = getchar()));
    if (neg) x = -x;
}

void scan(long long &x) {
    char c;
    x = 0;
    bool neg = false;
    while (!isdigit(c = getchar())) {
        if (c == '-') neg = true;
    }
    do {
        x = x * 10 + (c - '0');
    } while (isdigit(c = getchar()));
    if (neg) x = -x;
}

long long n, k, MOD;
int fact[262155];
int invFact[262155];

int powerMod(int base, long long exp) {
    int res = 1;
    while (exp) {
        if (exp & 1) {
            res = (long long)res * base % MOD;
        }
        base = (long long)base * base % MOD;
        exp >>= 1;
    }
    return res;
}

int dp[262155][31];
bool seen[262155][31];
int lg[262155];

int v2(int x) {
    int cnt = 0;
    while ((x & 1) == 0 && x) {
        ++cnt;
        x >>= 1;
    }
    return cnt;
}

int v2sum[262155];

int comb(int N, int M) {
    return (long long)fact[N] * invFact[M] % MOD * invFact[N - M] % MOD;
}

int dfs(int N, int K) {
    if (N == 0) return 1;
    if (K == 0) return 0;
    if (dp[N][K] != -1) return dp[N][K];

    int step = 1 << lg[N];
    int sum = 0;
    for (int i = N; i >= step; i -= 2) {
        sum = (sum + (long long)comb(N, i) * dfs(N - i, K - 1) % MOD * K) % MOD;
    }
    return dp[N][K] = sum;
}

vector<pair<int, int>> order;

int bfs(int N, int K) {
    queue<pair<int, int>> q;
    q.push({N, K});

    while (!q.empty()) {
        int curN = q.front().first;
        int curK = q.front().second;
        q.pop();
        order.push_back({curN, curK});

        if (curN == 0 || curK == 0) continue;

        int step = 1 << lg[curN];
        for (int i = curN; i >= step; i -= 2) {
            if (v2sum[i] + v2sum[curN - i] == v2sum[curN] && !seen[curN - i][curK - 1]) {
                seen[curN - i][curK - 1] = true;
                q.push({curN - i, curK - 1});
            }
        }
    }

    for (int i = order.size() - 1; i >= 0; --i) {
        int curN = order[i].first;
        int curK = order[i].second;

        if (curN == 0) {
            dp[curN][curK] = 1;
            continue;
        }
        if (curK == 0) {
            dp[curN][curK] = 0;
            continue;
        }

        int step = 1 << lg[curN];
        for (int i = curN; i >= step; i -= 2) {
            if (v2sum[i] + v2sum[curN - i] == v2sum[curN]) {
                dp[curN][curK] = (dp[curN][curK] + (long long)comb(curN, i) * dp[curN - i][curK - 1] % MOD * curK) % MOD;
            }
        }
    }

    return dp[N][K];
}

int main() {
    scan(n);
    scan(k);
    scan(MOD);

    fact[0] = 1;
    memset(seen, 0, sizeof(seen));
    lg[0] = -1;

    for (int i = 1; i <= 262150; ++i) {
        fact[i] = (long long)fact[i - 1] * i % MOD;
        lg[i] = lg[i >> 1] + 1;
        v2sum[i] = v2sum[i - 1] + v2(i);
    }

    invFact[262150] = powerMod(fact[262150], MOD - 2);
    for (int i = 262149; i >= 1; --i) {
        invFact[i] = (long long)invFact[i + 1] * (i + 1) % MOD;
    }

    invFact[0] = invFact[1];

    if (n & 1) {
        cout << powerMod(k, n) << '\n';
    } else {
        int total = powerMod(k, n);
        int result = bfs(n, k);
        cout << ((total - result) % MOD + MOD) % MOD;
    }
}
